require_once __DIR__.'/includes/admin_check.php';$items=$pdo->query("SELECT p.*,(SELECT COUNT(*) FROM screenshots s WHERE s.product_id=p.id) screenshot_count FROM products p ORDER BY p.created_at DESC")->fetchAll();$pageTitle='Quản trị | HENDY';require __DIR__.'/includes/header.php';?><div class="admin-heading"><div><div class="eyebrow">CONTROL CENTER</div><h1>Quản trị nội dung</h1><p class="muted">Quản lý sản phẩm và hình ảnh website.</p></div><a class="button primary" href="admin_add.php">＋ Thêm sản phẩm</a></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Sản phẩm</th><th>Danh mục</th><th>Giá</th><th>Ảnh</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><strong><?=e($p['title'])?></strong><small>#<?=(int)$p['id']?></small></td><td><?=e($p['category'])?></td><td><?=e($p['price'])?></td><td><?=(int)$p['screenshot_count']?></td><td><span class="status <?=e($p['status'])?>"><?=$p['status']==='published'?'Đang hiển thị':'Bản nháp'?></span></td><td class="actions"><a href="detail.php?id=<?=(int)$p['id']?>">Xem</a><a href="admin_edit.php?id=<?=(int)$p['id']?>">Sửa</a><form method="post" action="admin_delete.php" onsubmit="return confirm('Xóa sản phẩm này và toàn bộ ảnh?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="link-danger">Xóa</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$items):?><div class="empty-state"><h3>Chưa có sản phẩm</h3><a href="admin_add.php">Thêm sản phẩm đầu tiên</a></div><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>